(()=>{
  const STORE='franklinNavigator.savedActionPlans.v1';
  const RELEASE='FR-NAV1.9.0-CANDIDATE-R34';
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const safeRead=()=>{try{const v=JSON.parse(localStorage.getItem(STORE)||'[]');return Array.isArray(v)?v.slice(0,20):[]}catch{return []}};
  const safeWrite=v=>{try{localStorage.setItem(STORE,JSON.stringify(v.slice(0,20)));return true}catch{return false}};
  const dateText=(v,es)=>{if(!/^\d{4}-\d{2}-\d{2}$/.test(String(v||'')))return es?'Sin fecha de seguimiento':'No follow-up date';try{return new Intl.DateTimeFormat(es?'es-US':'en-US',{year:'numeric',month:'short',day:'numeric'}).format(new Date(v+'T12:00:00'))}catch{return v}};
  const configs={
    benefits_health:{title:{en:'Benefits + health follow-through',es:'Seguimiento de beneficios + salud'},counter:'benefits_health_plan_built',route:'/benefits-health-plan/',routeEs:'/es/plan-beneficios-salud/',themes:{coverage:{en:'Coverage, eligibility or renewal',es:'Cobertura, elegibilidad o renovación'},care:{en:'Care or appointment coordination',es:'Coordinación de atención o citas'},billing:{en:'Bills, EOBs or authorization paperwork',es:'Facturas, EOB o autorizaciones'},transport:{en:'Transportation or access',es:'Transporte o acceso'},records:{en:'Documents and dated records',es:'Documentos y registros con fecha'},household:{en:'Home or caregiver impact',es:'Impacto en el hogar o cuidador'}},actions:{en:['Confirm the current rule, eligibility or coverage process at the responsible source.','Separate care questions from coverage/billing questions.','Gather only the records the responsible source says are needed.','Write down questions before calling an agency, insurer, provider or professional.'],es:['Confirma la regla, elegibilidad o proceso de cobertura actual en la fuente responsable.','Separa las preguntas de atención de las preguntas de cobertura/facturación.','Reúne solo los documentos que la fuente responsable indique.','Anota preguntas antes de llamar a una agencia, aseguradora, proveedor o profesional.']},routes:[['Health help','/health-help/'],['Appeal & review prep','/appeal-review-prep/'],['Chronology & evidence','/chronology-evidence/'],['Transportation','/getting-around/']]},
    work_income:{title:{en:'Work + income follow-through',es:'Seguimiento de trabajo + ingresos'},counter:'work_income_plan_built',route:'/work-income-plan/',routeEs:'/es/plan-trabajo-ingresos/',themes:{job:{en:'Job change, application or career step',es:'Cambio de empleo, solicitud o carrera'},pay:{en:'Pay, hours or workplace benefit notice',es:'Pago, horas o aviso de beneficio laboral'},coverage:{en:'Health coverage changed with work',es:'Cobertura de salud cambió con el trabajo'},support:{en:'Public support or unemployment starting point',es:'Apoyo público o desempleo'},money:{en:'Household budget, debt or financial pressure',es:'Presupuesto, deuda o presión financiera'},legal:{en:'Legal, contract or administrative notice',es:'Aviso legal, contractual o administrativo'},transport:{en:'Transportation affecting work',es:'Transporte que afecta el trabajo'}},actions:{en:['Confirm whether the job, program, benefit or notice is still current at its original source.','Keep job/employer facts separate from legal or benefit conclusions.','Organize dated notices, pay/benefit records and questions before a professional conversation.','Use your own records—not Franklin Navigator activity—to judge financial outcomes.'],es:['Confirma en la fuente original si el empleo, programa, beneficio o aviso sigue vigente.','Separa los hechos laborales de conclusiones legales o de beneficios.','Organiza avisos con fecha, registros de pago/beneficios y preguntas antes de hablar con un profesional.','Usa tus propios registros —no la actividad de Franklin Navigator— para evaluar resultados financieros.']},routes:[['Jobs & internships','/jobs-internships/'],['Legal help','/legal-help/'],['Appeal & review prep','/appeal-review-prep/'],['Notice organizer','/notice-claim-organizer/']]},
    caregiver:{title:{en:'Senior + caregiver coordination',es:'Coordinación para adulto mayor + cuidador'},counter:'caregiver_plan_built',route:'/caregiver-coordination-plan/',routeEs:'/es/plan-cuidado-apoyo/',themes:{care:{en:'Care and appointment coordination',es:'Coordinación de atención y citas'},home:{en:'Home safety or support',es:'Seguridad o apoyo en el hogar'},transport:{en:'Transportation and mobility',es:'Transporte y movilidad'},benefits:{en:'Benefits, coverage or paperwork',es:'Beneficios, cobertura o trámites'},documents:{en:'Important documents and questions',es:'Documentos importantes y preguntas'},community:{en:'Community, respite or social support',es:'Apoyo comunitario, respiro o social'}},actions:{en:['Identify the next one or two conversations rather than trying to solve every need at once.','Confirm current schedules, eligibility and service areas directly.','Keep medical details in appropriate private records, not in this planner.','Ask permission before sharing another person’s information with a professional or organization.'],es:['Identifica una o dos conversaciones siguientes en vez de intentar resolver todo a la vez.','Confirma horarios, elegibilidad y áreas de servicio directamente.','Mantén los detalles médicos en registros privados apropiados, no en este planificador.','Pide permiso antes de compartir información de otra persona con un profesional u organización.']},routes:[['Senior & caregiver support','/senior-caregiver/'],['Health help','/health-help/'],['Home & property','/home-property-help/'],['Transportation','/getting-around/']]},
    member:{title:{en:'Community Member starter plan',es:'Plan inicial de miembro comunitario'},counter:'member_starter_plan_built',route:'/member-starter-plan/',routeEs:'/member-starter-plan/',themes:{profile:{en:'Review or improve the public profile',es:'Revisar o mejorar el perfil público'},participation:{en:'Choose a community participation idea',es:'Elegir una idea de participación comunitaria'},growth:{en:'Prepare a Growth Desk starter action',es:'Preparar una acción inicial de Growth Desk'},bilingual:{en:'Prepare English, Spanish or bilingual participation',es:'Preparar participación en inglés, español o bilingüe'},share:{en:'Prepare a profile/share or QR idea',es:'Preparar una idea de perfil/compartir o QR'},support:{en:'Know support and cancellation routes',es:'Conocer rutas de apoyo y cancelación'}},actions:{en:['Start with the correct public profile and factual corrections, which remain free.','Choose one useful community action that can become first value after verified activation.','Keep paid membership separate from factual truth, credentials and organic relevance.','Do not treat a click, inquiry or payment as proof of a customer or retained member.'],es:['Empieza con el perfil público correcto y correcciones factuales, que siguen siendo gratuitas.','Elige una acción comunitaria útil que pueda convertirse en primer valor tras activación verificada.','Mantén la membresía pagada separada de la verdad factual, credenciales y relevancia orgánica.','No trates un clic, consulta o pago como prueba de cliente o miembro retenido.']},routes:[['Find or review profile','/claim-profile/'],['Member profile preview','/member-profile-preview/'],['Growth Desk','/growth-desk/'],['Member support','/member-support/']]}
  };
  const renderSaved=()=>{
    document.querySelectorAll('[data-r34-saved-plans]').forEach(root=>{
      const es=document.documentElement.lang==='es',items=safeRead();root.replaceChildren();
      if(!items.length){const p=document.createElement('p');p.className='empty-state';p.textContent=es?'Todavía no hay planes de acción guardados.':'No saved action plans yet.';root.append(p);return}
      const doneCount=items.filter(x=>x.completedAt).length;const summary=document.createElement('p');summary.className='r34-progress-summary';summary.textContent=es?`${doneCount} completado${doneCount===1?'':'s'} · ${items.length-doneCount} en progreso`:`${doneCount} completed · ${items.length-doneCount} in progress`;root.append(summary);const grid=document.createElement('div');grid.className='grid three r34-saved-grid';
      items.forEach(item=>{const cfg=configs[item.type];if(!cfg)return;const card=document.createElement('article');card.className='card r34-saved-card'+(item.completedAt?' is-complete':'');const h=document.createElement('h3');h.textContent=cfg.title[es?'es':'en'];const p=document.createElement('p');p.textContent=(item.themes||[]).map(k=>cfg.themes[k]?.[es?'es':'en']).filter(Boolean).join(' · ')|| (es?'Plan guardado':'Saved plan');const meta=document.createElement('p');meta.className='fine-print';meta.textContent=dateText(item.followUpDate,es)+(item.completedAt?(es?' · Completado':' · Completed'):'');const actions=document.createElement('div');actions.className='actions';const open=document.createElement('a');open.className='button small';open.href=es?cfg.routeEs:cfg.route;open.textContent=es?'Abrir':'Open';const complete=document.createElement('button');complete.type='button';complete.className='button small';complete.textContent=item.completedAt?(es?'Reabrir':'Reopen'):(es?'Marcar hecho':'Mark done');complete.addEventListener('click',()=>{const next=safeRead().map(x=>x.id===item.id?{...x,completedAt:x.completedAt?null:new Date().toISOString()}:x);if(safeWrite(next)){window.FranklinProductHealth?.record('plan_completion_changed');renderSaved()}});const remove=document.createElement('button');remove.type='button';remove.className='button small';remove.textContent=es?'Quitar':'Remove';remove.addEventListener('click',()=>{safeWrite(safeRead().filter(x=>x.id!==item.id));renderSaved()});actions.append(open,complete,remove);card.append(h,p,meta,actions);grid.append(card)});root.append(grid)
    })
  };
  const savePlan=(packet,status,es)=>{const items=safeRead();items.unshift({id:`p-${Date.now()}-${Math.random().toString(16).slice(2,8)}`,type:packet.type,themes:packet.themes,followUpDate:packet.followUpDate||'',savedAt:new Date().toISOString()});if(safeWrite(items)){status.textContent=es?'Plan guardado en My Franklin solo en este dispositivo.':'Plan saved to My Franklin on this device only.';window.FranklinProductHealth?.record('plan_saved_to_my_franklin');renderSaved()}else status.textContent=es?'Este navegador no permitió guardar el plan. Puedes imprimirlo o copiarlo.':'This browser did not allow saving. You can still print or copy the plan.'};
  const safeShare=async(btn,url,title,es)=>{try{if(navigator.share){await navigator.share({title,url})}else if(navigator.clipboard){await navigator.clipboard.writeText(url)}else throw new Error('no share');btn.textContent=es?'Enlace listo':'Link ready';window.FranklinProductHealth?.record('safe_share_used')}catch{btn.textContent=es?'Copia la URL del navegador':'Copy the browser URL'}};
  document.querySelectorAll('[data-r34-plan]').forEach(root=>{
    const es=document.documentElement.lang==='es',type=root.dataset.r34Plan,cfg=configs[type];if(!cfg)return;const form=root.querySelector('form'),out=root.querySelector('[data-r34-output]'),status=root.querySelector('[data-r34-status]'),copy=root.querySelector('[data-r34-copy]'),download=root.querySelector('[data-r34-download]'),print=root.querySelector('[data-r34-print]'),save=root.querySelector('[data-r34-save]'),share=root.querySelector('[data-r34-share]');let packet=null;
    const lang=es?'es':'en';
    const build=()=>{const themes=[...form.querySelectorAll('input[name="theme"]:checked')].map(x=>x.value).filter(x=>cfg.themes[x]);if(!themes.length){out.innerHTML=`<p class="empty-state">${esc(es?'Elige al menos un tema.':'Choose at least one topic.')}</p>`;status.textContent=es?'Elige al menos un tema.':'Choose at least one topic.';return}const follow=form.elements.followUp?.value||'',stage=form.elements.stage?.value||'starting';packet={schemaVersion:'franklin.r34.follow-through.device-only.v1',release:RELEASE,community:'FRANKLIN_TN',type,themes,followUpDate:/^\d{4}-\d{2}-\d{2}$/.test(follow)?follow:null,stage,privacy:{freeNarrativeCollected:false,documentUpload:false,identifiersRequested:false,networkSubmission:false},boundary:es?'Organiza próximos pasos; no decide elegibilidad, cobertura, derechos, diagnóstico, responsabilidad, resultado ni plazo válido.':'Organizes next steps; does not decide eligibility, coverage, legal rights, diagnosis, liability, outcome or a valid deadline.'};const labels=themes.map(k=>cfg.themes[k][lang]);out.innerHTML=`<div class="eyebrow">${esc(cfg.title[lang])}</div><h3>${esc(es?'Temas conectados':'Connected topics')}</h3><ul>${labels.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h3>${esc(es?'Próximos pasos':'Next steps')}</h3><ol>${cfg.actions[lang].map(x=>`<li>${esc(x)}</li>`).join('')}</ol><p><strong>${esc(es?'Fecha de seguimiento elegida':'Chosen follow-up date')}:</strong> ${esc(dateText(packet.followUpDate,es))}</p><p class="r34-boundary">${esc(packet.boundary)}</p><p class="r34-privacy">${esc(es?'Privacidad: este plan se crea en tu navegador. No escribas información médica, legal, financiera, de cuenta o de otra persona.':'Privacy: this plan is built in your browser. Do not enter medical, legal, financial, account or another person’s private information.')}</p>`;copy.disabled=download.disabled=print.disabled=save.disabled=false;status.textContent=es?'Plan creado.':'Plan built.';out.focus();window.FranklinProductHealth?.record(cfg.counter)};
    form.addEventListener('submit',e=>{e.preventDefault();build()});form.addEventListener('reset',()=>setTimeout(()=>{packet=null;out.innerHTML=`<p class="empty-state">${esc(es?'Elige temas para crear tu plan.':'Choose topics to build your plan.')}</p>`;copy.disabled=download.disabled=print.disabled=save.disabled=true;status.textContent=''},0));
    copy?.addEventListener('click',async()=>{if(!packet)return;const text=out.innerText;try{await navigator.clipboard.writeText(text);status.textContent=es?'Plan copiado.':'Plan copied.'}catch{status.textContent=es?'Selecciona y copia el plan manualmente.':'Select and copy the plan manually.'}});
    download?.addEventListener('click',()=>{if(!packet)return;const blob=new Blob([JSON.stringify(packet,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`franklin-${type}-plan.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)});
    print?.addEventListener('click',()=>packet&&window.print());save?.addEventListener('click',()=>packet&&savePlan(packet,status,es));share?.addEventListener('click',()=>safeShare(share,location.origin+(es?cfg.routeEs:cfg.route),cfg.title[lang],es));
  });
  document.querySelectorAll('[data-r34-safe-share]').forEach(btn=>{const es=document.documentElement.lang==='es';btn.addEventListener('click',()=>safeShare(btn,location.origin+location.pathname,document.title,es))});
  renderSaved();window.FranklinR34SavedPlans=Object.freeze({render:renderSaved,clear:()=>{try{localStorage.removeItem(STORE)}catch{}renderSaved()}});
})();